#include <fstream>
#include <iostream>

int main() {
    std::ofstream out1("example.txt");  // Constructs a basic_ofstream object
    out1 << "Hello, World!";  // Writes to the file
    std::ofstream out2(std::move(out1));  // Invokes the move constructor
    out2 << " This is moved.";  // Uses the moved stream
    return 0;
}
